"""Public suffix rules used to reject blocklist entries that would block a registry.

The lists are the ICANN and private sections of the Public Suffix List
(https://publicsuffix.org/list/public_suffix_list.dat), Mozilla Public License 2.0.
Wildcard rules are stored as the parent (``*.ck`` becomes ``ck``).
"""

from __future__ import annotations

import base64
import zlib

def _unpack(blob: str) -> frozenset[str]:
    raw = zlib.decompress(base64.b64decode(blob))
    if not raw:
        return frozenset()
    return frozenset(raw.decode().split("\0"))

_EXACT = _unpack("")
_WILDCARDS = _unpack("")
_EXCEPTIONS = _unpack("eNpFzEEKwCAMRNGeKHeaplJtqAlVCbl9wYUu32cYLj1I4GiQQo8dPEPpkBgtj530TAsVtwYWG8z00+1UL+y3UNGMd+7dnVh+L9kreg==")


def is_public_suffix(domain: str) -> bool:
    """True when ``domain`` is a TLD or a public suffix, not a registrable name."""
    name = domain.strip().lower().rstrip(".")
    if not name or name in _EXCEPTIONS:
        return False
    if "." not in name or name in _EXACT:
        return True
    parent = name.split(".", 1)[1]
    return parent in _WILDCARDS
